#!/usr/bin/env bash
set -euo pipefail
echo "Adaug automatizarea zilnica: workflow GitHub Actions + script email"

mkdir -p .github/workflows
base64 -d > send_report_email.py << 'B64_EMAIL'

B64_EMAIL

base64 -d > .github/workflows/daily-report.yml << 'B64_YML'

B64_YML

python3 -m py_compile send_report_email.py && echo "COMPILE OK (email script)"
python3 -c "import yaml" 2>/dev/null && python3 -c "import yaml; yaml.safe_load(open(\".github/workflows/daily-report.yml\"))" && echo "YAML VALID" || echo "yaml module lipseste, sar peste validare YAML (nu e o problema)"
echo "Gata. Verifica cu: git status"
